//! Golden parity tests against ToJyutping 3.2.0. Fixtures are generated by
//! `parity/gen_fixtures.py`
//! (`pixi run --manifest-path crates/ports/tojyutping/pixi.toml fixtures`).

use std::collections::{BTreeMap, BTreeSet};

use serde::Deserialize;
use tojyutping::utils;

type JyutpingList = Vec<(String, Option<String>)>;

fn load<T: for<'de> Deserialize<'de>>(name: &str) -> T {
  let path = format!("{}/tests/fixtures/{name}", env!("CARGO_MANIFEST_DIR"));
  let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
  serde_json::from_str(&text).unwrap_or_else(|e| panic!("{path}: {e}"))
}

/// Asserts every case and reports the number of mismatches.
fn check_list(name: &str, cases: &[(String, JyutpingList)]) {
  let mut failures = Vec::new();
  for (input, expected) in cases {
    let actual = tojyutping::get_jyutping_list(input);
    if &actual != expected {
      failures.push(format!("{input:?}: expected {expected:?}, got {actual:?}"));
    }
  }
  eprintln!(
    "{name}: {}/{} exact",
    cases.len() - failures.len(),
    cases.len()
  );
  assert!(
    failures.is_empty(),
    "{} mismatches:\n{}",
    failures.len(),
    failures[..failures.len().min(20)].join("\n")
  );
}

#[test]
fn chars() {
  let cases: Vec<(String, JyutpingList)> = load("chars.json");
  assert_eq!(cases.len(), tojyutping::trie::root().children.len());
  check_list("chars", &cases);
}

#[test]
fn words() {
  let cases: Vec<(String, JyutpingList)> = load("words.json");
  assert!(cases.len() >= 10_000);
  check_list("words", &cases);
}

#[derive(Deserialize)]
struct Sentence {
  text: String,
  list: JyutpingList,
  jyutping: String,
  jyutping_text: String,
}

#[test]
fn sentences() {
  let cases: Vec<Sentence> = load("sentences.json");
  assert!(cases.len() >= 1_000);
  let mut failures = Vec::new();
  let (mut list_ok, mut jp_ok, mut text_ok) = (0, 0, 0);
  for case in &cases {
    let list = tojyutping::get_jyutping_list(&case.text);
    let jp = tojyutping::get_jyutping(&case.text);
    let text = tojyutping::get_jyutping_text(&case.text);
    if list == case.list {
      list_ok += 1;
    } else {
      failures.push(format!("list {:?}: got {list:?}", case.text));
    }
    if jp == case.jyutping {
      jp_ok += 1;
    } else {
      failures.push(format!(
        "get_jyutping {:?}: expected {:?}, got {jp:?}",
        case.text, case.jyutping
      ));
    }
    if text == case.jyutping_text {
      text_ok += 1;
    } else {
      failures.push(format!(
        "get_jyutping_text {:?}: expected {:?}, got {text:?}",
        case.text, case.jyutping_text
      ));
    }
  }
  let n = cases.len();
  eprintln!(
    "sentences: get_jyutping_list {list_ok}/{n}, get_jyutping {jp_ok}/{n}, get_jyutping_text {text_ok}/{n}"
  );
  assert!(
    failures.is_empty(),
    "{} mismatches:\n{}",
    failures.len(),
    failures[..failures.len().min(20)].join("\n")
  );
}

#[derive(Deserialize)]
struct Constants {
  punct_dict: BTreeMap<char, char>,
  left_bracket: BTreeSet<char>,
  right_bracket: BTreeSet<char>,
  left_punct: BTreeSet<char>,
  right_punct: BTreeSet<char>,
  other_punct: BTreeSet<char>,
  left_or_other_punct: BTreeSet<char>,
  right_or_other_punct: BTreeSet<char>,
  minus_signs: BTreeSet<char>,
  decimal_seps: BTreeSet<char>,
  digits: BTreeSet<char>,
  isspace: BTreeSet<char>,
}

#[test]
fn constants() {
  let c: Constants = load("constants.json");
  let set = |s: &str| s.chars().collect::<BTreeSet<char>>();
  let punct_dict: BTreeMap<char, char> =
    utils::punct_dict().iter().map(|(&k, &v)| (k, v)).collect();
  assert_eq!(punct_dict, c.punct_dict);
  assert_eq!(set(utils::LEFT_BRACKET), c.left_bracket);
  assert_eq!(set(utils::RIGHT_BRACKET), c.right_bracket);
  assert_eq!(set(utils::LEFT_PUNCT), c.left_punct);
  assert_eq!(set(utils::RIGHT_PUNCT), c.right_punct);
  assert_eq!(set(utils::OTHER_PUNCT), c.other_punct);
  assert_eq!(set(utils::LEFT_OR_OTHER_PUNCT), c.left_or_other_punct);
  assert_eq!(set(utils::RIGHT_OR_OTHER_PUNCT), c.right_or_other_punct);
  assert_eq!(set(utils::MINUS_SIGNS), c.minus_signs);
  assert_eq!(set(utils::DECIMAL_SEPS), c.decimal_seps);
  assert_eq!(set(utils::DIGITS), c.digits);
  let isspace: BTreeSet<char> = (0..=0x10FFFFu32)
    .filter_map(char::from_u32)
    .filter(|&ch| utils::py_isspace(ch))
    .collect();
  assert_eq!(isspace, c.isspace);
}
